import {CONTENT} from './content.js';
import {SCENES,readRoute,routeUrl,nextScene,previousScene,validLanguage,DURATIONS,automaticProgress,shouldAdvance} from './learning.js';
import {Ocean,SeaSound,drawTransfer} from './world.js';
import {drawShell,drawMussel,drawLivingSnail,drawClosedMussel,readyGrowth,artImage} from './art.js';
import {PaintedWater} from './immersion.js';
const $=s=>document.querySelector(s),sceneElement=$('#scene'),aboutElement=$('#about');
const initial=readRoute(location.href);let lang=initial.lang,scene=initial.scene,lastScene='start',routeDepth=0,elapsed=0,playing=false,ready=false,transitioning=false,keepsake='snail',sound=false,ambientPaused=false;
const motion=!matchMedia('(prefers-reduced-motion: reduce)').matches;
const snapshots=new Map(),ocean=new Ocean($('#water')),seaSound=new SeaSound(),paintedWater=new PaintedWater($('#ocean'));
const c=()=>CONTENT[lang],escape=s=>String(s??'').replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
const arrow='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 12h16m-6-6 6 6-6 6"/></svg>';
const button=(text,action,kind='primary')=>`<button class="${kind}" data-action="${action}">${escape(text)}${kind==='primary'?arrow:''}</button>`;
const announce=text=>{$('#status').textContent=text;};
function applyPreferences(){const t=c();document.documentElement.lang=lang;const ambient=motion&&!ambientPaused&&(playing||scene==='start'||scene==='ending');document.body.dataset.motion=ambient?'on':'off';ocean.setActive(ambient);paintedWater.setActive(ambient);$('#motion').setAttribute('aria-label',t.controls[(playing||ambient)?'pause':'resume']);$('#motion').setAttribute('aria-pressed',String(!(playing||ambient)));$('#sound').setAttribute('aria-label',t.controls[sound?'sound-off':'sound-on']);$('#sound').setAttribute('aria-pressed',String(sound));$('#fullscreen').setAttribute('aria-label',t.controls.fullscreen);$('#back span').textContent=t.controls.back;$('#home').textContent=t.controls.home;$('#advance').textContent=t.controls.next;$('#advance').hidden=!DURATIONS[scene];$('.languages').setAttribute('aria-label',t.controls.language);$('#progress').setAttribute('aria-label',t.controls.progress);document.querySelectorAll('[data-lang]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.lang===lang)));}
history.replaceState({coquillages:true,depth:0,lastScene},'',routeUrl(location.href,scene,lang));
async function go(id,{restore=false}={}){if(transitioning||id===scene)return;snapshots.set(scene,elapsed);if(scene!=='about')lastScene=scene;transitioning=true;document.documentElement.dataset.direction=SCENES.indexOf(id)>=SCENES.indexOf(scene)?'forward':'back';const change=()=>{scene=id;elapsed=restore?(snapshots.get(id)||0):0;routeDepth++;history.pushState({coquillages:true,depth:routeDepth,lastScene},'',routeUrl(location.href,id,lang));render(true);};if(document.startViewTransition&&motion){await document.startViewTransition(change).finished.catch(()=>{});}else change();transitioning=false;}
function back(){playing=false;if(routeDepth>0)history.back();else if(scene==='about')go(lastScene,{restore:true});else if(scene!=='start')go(previousScene(scene),{restore:true});else location.href='https://salonformat.com';applyPreferences();}
window.addEventListener('popstate',()=>{snapshots.set(scene,elapsed);const r=readRoute(location.href);scene=r.scene;lang=r.lang;elapsed=snapshots.get(scene)||0;routeDepth=history.state?.depth||0;playing=false;render(true);});
$('#back').addEventListener('click',back);$('#home').addEventListener('click',()=>{playing=false;go('start');});$('#advance').addEventListener('click',()=>go(nextScene(scene)));
$('#motion').addEventListener('click',()=>{if(scene==='start'||scene==='ending'){ambientPaused=!ambientPaused;applyPreferences();}else if(DURATIONS[scene]){if(elapsed>=DURATIONS[scene])elapsed=0;playing=!playing;ambientPaused=!playing;applyPreferences();}});
document.querySelectorAll('[data-lang]').forEach(b=>b.addEventListener('click',()=>{lang=b.dataset.lang;history.replaceState({...history.state},'',routeUrl(location.href,scene,lang));render(false);}));
$('#sound').addEventListener('click',async()=>{try{await seaSound.set(!sound);sound=!sound;applyPreferences();}catch{announce(c().ui.audioUnavailable);}});
$('#fullscreen').addEventListener('click',async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();}catch{announce(c().ui.fullscreenUnavailable);}});
window.addEventListener('pointermove',e=>{if(!motion||!playing)return;document.documentElement.style.setProperty('--px',(e.clientX/innerWidth-.5).toFixed(3));document.documentElement.style.setProperty('--py',(e.clientY/innerHeight-.5).toFixed(3));},{passive:true});
async function prepare(id){const sources={animal:['snail.png'],edge:['snail-shell.png'],bivalve:['mussel-closed.png'],transfer:['scallop.png']};try{await Promise.all((sources[id]||[]).map(name=>artImage('assets/'+name).decode()));if(id==='growth')await readyGrowth('snail');if(id==='bivalve')await readyGrowth('mussel');if(id==='ending')await readyGrowth(keepsake==='snail'?'snail':'mussel');if(scene===id){ready=true;sceneElement.dataset.ready='true';updateDrawing();}}catch{if(scene===id){ready=true;announce(c().controls.loading);}}}
function render(focus=false){ready=false;const t=c(),s=t[scene],index=SCENES.indexOf(scene);document.body.dataset.scene=scene;paintedWater.setScene(scene);ocean.setScene(scene);if(scene==='start'||scene==='ending'||scene==='about')playing=false;applyPreferences();document.title=(s?.title||t.controls['source-title'])+' — SALONFORMAT';$('#progress').innerHTML=SCENES.map((id,i)=>`<a href="${routeUrl(location.href,id,lang)}" data-scene="${id}" ${id===scene?'aria-current="step"':''} class="${i<index?'done':''}" aria-label="${escape(t.ui.progressNames[i])}"></a>`).join('');if(scene==='about'){sceneElement.hidden=true;aboutElement.hidden=false;renderAbout();return;}sceneElement.hidden=false;aboutElement.hidden=true;let copy='',stage='';const title=`<h1 id="scene-title" tabindex="-1">${escape(s.title)}</h1>`;
if(scene==='start'){copy=`<div class="brand-title">Coquillages</div>${title}<p>${escape(s.body)}</p><p class="journey-hint">${escape(s.hint)}</p><div class="actions">${button(s.action,'begin')}</div>`;}
if(scene==='animal'){copy=`${title}<p>${escape(s.body)}</p><div class="timed-copy" data-after="3"><p>${escape(t.why.body)}</p></div>`;stage=`<canvas id="living-snail" class="growth-canvas" role="img" aria-label="${escape(s.body)}"></canvas>`;}
if(scene==='edge'){copy=`${title}<p>${escape(s.body)}</p><div class="timed-copy" data-after="4"><p>${escape(s.extra)}</p></div>`;stage=`<img src="assets/snail-shell.png" alt="${escape(s.title)}"><div class="macro-caption">${escape({de:"Die Schalenöffnung",fr:"L’ouverture de la coquille",en:"The shell opening"}[lang])}</div>`;}
if(scene==='growth'){copy=`${title}<p>${escape(s.instruction)}</p><div class="timed-copy" data-after="9"><p>${escape(s.after)}</p></div><p class="model-note">${escape(s['model-note'])}</p>`;stage=`<canvas id="shell-growth" class="growth-canvas" role="img" aria-label="${escape(s.after)}"></canvas><div class="drawn-label growth-old-label">${escape(s['old-label'])}</div><div id="growth-edge-label" class="drawn-label">${escape(s['new-label'])}</div>`;}
if(scene==='bivalve'){copy=`${title}<p>${escape(s.body)}</p><div class="timed-copy" data-after="7"><p>${escape(s.after)}</p></div>`;stage=`<canvas id="mussel-growth" class="growth-canvas" role="img" aria-label="${escape(s.body)}"></canvas>`;}
if(scene==='transfer'){copy=`${title}<p>${escape(s.body)}</p>`;stage=`<img src="assets/scallop.png" alt="${escape(s.title)}"><canvas id="transfer-growth" class="growth-canvas" aria-hidden="true"></canvas>`;}
if(scene==='ending'){copy=`${title}<p>${escape(s.body)}</p><p>${escape(s.transfer)}</p><h2 class="keepsake-heading">${escape(s['keepsake-title'])}</h2><div class="keepsake-options">${['snail','bivalve'].map(key=>`<button data-keepsake="${key}" aria-pressed="${keepsake===key}">${escape(s[key])}</button>`).join('')}</div><div class="actions">${button(s.download,'download')}${button(s.replay,'restart','secondary')}${button(s.sources,'about','text-button')}</div>`;stage=`<div class="card-preview"><div class="card-title">Coquillages</div><canvas id="card-drawing" role="img" aria-label="${escape(s['card-line-2'])}"></canvas><p>${escape(t.ui.whyCard)}<br>${escape(s['card-line-2'])}</p><small>${escape(s['card-note'])}<br>ISABELLA KOHOUT / SALONFORMAT</small></div>`;}
sceneElement.className='scene-'+scene;sceneElement.innerHTML=`<div class="scene-copy">${copy}</div><div class="stage">${stage}</div>`;prepare(scene);if(focus){$('#scene-title').focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});$('#experience').scrollTop=0;}updateTimedCopy();}
function updateTimedCopy(){document.querySelectorAll('[data-after]').forEach(el=>{el.classList.toggle('revealed',elapsed>=Number(el.dataset.after));el.setAttribute('aria-hidden',String(elapsed<Number(el.dataset.after)));});$('#scene-time').style.setProperty('--progress',String(DURATIONS[scene]?Math.min(1,elapsed/DURATIONS[scene]):0));}
function updateDrawing(){const shell=$('#shell-growth');if(shell){const point=drawShell(shell,automaticProgress(scene,elapsed));const label=$('#growth-edge-label');if(point&&label){label.style.left=Math.max(0,Math.min(shell.clientWidth-145,point.x+10))+'px';label.style.top=Math.min(shell.clientHeight-45,point.y+20)+'px';}}const living=$('#living-snail');if(living)drawLivingSnail(living,elapsed,motion&&playing);const mussel=$('#mussel-growth');if(mussel){if(elapsed<3)drawClosedMussel(mussel);else drawMussel(mussel,automaticProgress(scene,elapsed));}const transfer=$('#transfer-growth');if(transfer){if(elapsed>=3)drawTransfer(transfer,artImage('assets/scallop.png'));else transfer.getContext('2d').clearRect(0,0,transfer.width,transfer.height);}const card=$('#card-drawing');if(card)(keepsake==='snail'?drawShell:drawMussel)(card,1);}
let last=performance.now(),lastDraw=0;function tick(now){const dt=Math.min((now-last)/1000,.1);last=now;if(playing&&ready&&!transitioning&&!document.hidden&&DURATIONS[scene]){elapsed+=dt;updateTimedCopy();if(shouldAdvance(scene,elapsed))go(nextScene(scene));}if(now-lastDraw>80&&ready&&playing&&!document.hidden){updateDrawing();lastDraw=now;}requestAnimationFrame(tick);}requestAnimationFrame(tick);
window.addEventListener('resize',updateDrawing);window.addEventListener('artready',updateDrawing);
document.addEventListener('click',event=>{const anchor=event.target.closest('a[data-scene]');if(anchor){event.preventDefault();playing=false;go(anchor.dataset.scene);return;}const keep=event.target.closest('[data-keepsake]');if(keep){keepsake=keep.dataset.keepsake;render();return;}const action=event.target.closest('[data-action]')?.dataset.action;if(action==='begin'){playing=true;ambientPaused=false;go('animal');}if(action==='restart'){snapshots.clear();playing=false;go('start');}if(action==='about')go('about');if(action==='close-about')back();if(action==='download')downloadCard();});
function renderAbout(){const t=c();aboutElement.innerHTML=`<h1 id="about-title" tabindex="-1">${escape(t.controls['source-title'])}</h1><p>${escape(t.controls['model-description'])}</p><h2>${escape(t.ui.research)}</h2><div class="source-links"><a href="https://www.nhm.ac.uk/discover/interesting-shells.html" target="_blank" rel="noopener noreferrer">Natural History Museum</a><a href="https://ocean.si.edu/ecosystems/shells-story" target="_blank" rel="noopener noreferrer">Smithsonian Ocean</a><a href="https://inpn.mnhn.fr/docs/communication/livretInpn/Livret-INPN-biodiversite-France-Mollusques-2023.pdf" target="_blank" rel="noopener noreferrer">MNHN</a></div><p class="sources-footer">${escape(t.ui.credits)}</p><div class="actions">${button(t.controls.back,'close-about')}</div>`;}

function wrap(ctx,text,x,y,width,lineHeight){let line='',yy=y;for(const word of text.split(' ')){const test=line?`${line} ${word}`:word;if(ctx.measureText(test).width>width&&line){ctx.fillText(line,x,yy);yy+=lineHeight;line=word;}else line=test;}ctx.fillText(line,x,yy);return yy+lineHeight;}
async function downloadCard(){
  try{
    await document.fonts.ready;
    const canvas=document.createElement('canvas');canvas.width=1400;canvas.height=1800;const ctx=canvas.getContext('2d');
    ctx.fillStyle='#f1e7d0';ctx.fillRect(0,0,1400,1800);ctx.fillStyle='#153e55';ctx.font='66px "Della Respira"';ctx.fillText('Coquillages',110,150);
    await readyGrowth(keepsake==='snail'?'snail':'mussel');
    const drawing=document.createElement('canvas');drawing.width=1160;drawing.height=800;(keepsake==='snail'?drawShell:drawMussel)(drawing,1);ctx.drawImage(drawing,120,215);
    ctx.font='48px "Della Respira"';let yy=wrap(ctx,c().ui.whyCard,110,1120,1160,69);ctx.font='42px "Josefin Sans"';yy=wrap(ctx,c().ending['card-line-1'],110,yy+60,1160,60);wrap(ctx,c().ending['card-line-2'],110,yy+15,1160,60);
    ctx.font='23px "Josefin Sans"';ctx.fillText(c().ending['card-note'],110,1610);ctx.fillText('ISABELLA KOHOUT / SALONFORMAT',110,1670);ctx.fillText('salonformat.com',110,1715);
    const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));if(!blob)throw new Error('Empty export');
    const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`coquillages-${lang}.png`;a.click();setTimeout(()=>URL.revokeObjectURL(url),60000);announce(c().ui.cardSaved);
  }catch{announce(c().controls['download-error']);const existing=$('#download-error');if(existing)existing.textContent=c().controls['download-error'];else{const p=document.createElement('p');p.id='download-error';p.className='feedback';p.setAttribute('role','alert');p.textContent=c().controls['download-error'];$('.scene-copy').append(p);}}
}


render(false);
document.fonts.ready.then(updateDrawing);
